623	        private async Task UpdateReferenceWithConfirmationAsync()
624	        {
625	            // Check if we have removed or inserted mods that require confirmation
626	            var removedMods = DiffLines.Where(line => line.ChangeType == DiffChangeType.Removed).ToList();
627	            var insertedMods = DiffLines.Where(line => line.ChangeType == DiffChangeType.Inserted).ToList();
628	
629	            bool hasRemovedMods = removedMods.Any();
630	            bool hasInsertedMods = insertedMods.Any();
631	
632	            if (hasRemovedMods || hasInsertedMods)
633	            {
634	                // Build risk-specific detail lines for each risky change type
635	                var detailLines = new System.Collections.Generic.List<string>();
636	
637	                if (hasRemovedMods)
638	                {
639	                    int count = removedMods.Count;
640	                    string removedDetail = count == 1
641	                        ? Texts.ConfirmRiskyDetail_RemovedSingular
642	                        : string.Format(Texts.ConfirmRiskyDetail_Removals, count);
643	                    detailLines.Add(removedDetail);
644	                }
645	
646	                if (hasInsertedMods)
647	                {
648	                    int count = insertedMods.Count;
649	                    string insertedDetail = count == 1
650	                        ? Texts.ConfirmRiskyDetail_InsertedSingular
651	                        : string.Format(Texts.ConfirmRiskyDetail_Insertions, count);
652	                    detailLines.Add(insertedDetail);
653	                }
654	
655	                string detailBlock = string.Join("\n", detailLines);
656	                string confirmMessage = string.Format(Texts.ConfirmUpdateMessage_RiskyChanges, detailBlock);
657	
658	                // Request confirmation from the view
659	                var eventArgs = new ConfirmationRequestedEventArgs(
660	                    Texts.ConfirmUpdateTitle,
661	                    confirmMessage,
662	                    ConfirmationIcon.Warning,
663	                    ConfirmationButton.YesNo);
664	                ConfirmationRequested?.Invoke(this, eventArgs);
665	
666	                if (eventArgs.Result != ConfirmationResult.Yes)
667	                {
668	                    DiffStatusMessage = Texts.ReferenceUpdateCancelledStatus;
669	                    return;
670	                }
671	            }
672	
673	            // Proceed with the update
674	            if (_mainViewModel.CreateReferenceCommand?.CanExecute(null) ?? false)
675	            {
676	                await _mainViewModel.CreateReferenceCommand.ExecuteAsync(null);
677	            }
678	        }
